// Diagnostic: dump OSMesgQueue state for the addresses in SCARS_QUEUES
// (comma/space separated hex). A stalled game is almost always a message that
// never arrives; this shows which queues are empty and who is waiting on them.
namespace {

constexpr int32_t kOsThreadIdOffset = 0x14;
constexpr int32_t kOsThreadNextOffset = 0x00;
constexpr int32_t kQueueBlockedRecv = 0x00;
constexpr int32_t kQueueValidCount = 0x08;
constexpr int32_t kQueueMsgCount = 0x10;

uint8_t* guest_byte(uint8_t* rdram, int32_t guest_address) {
    return &rdram[static_cast<uint64_t>(static_cast<int64_t>(guest_address)) - 0xFFFFFFFF80000000ull];
}

int32_t read_guest_word(uint8_t* rdram, int32_t guest_address) {
    return *reinterpret_cast<int32_t*>(guest_byte(rdram, guest_address));
}

int blocked_thread_count(uint8_t* rdram, int32_t head, char* text, size_t text_size) {
    int count = 0;
    size_t used = 0;
    int32_t current = head;
    while (current != 0 && count < 8) {
        const int32_t id = read_guest_word(rdram, current + kOsThreadIdOffset);
        const int written = std::snprintf(text + used, text_size > used ? text_size - used : 0, "%s%d", count ? "," : "",
                                          id);
        if (written > 0) {
            used += static_cast<size_t>(written);
        }
        current = read_guest_word(rdram, current + kOsThreadNextOffset);
        count++;
    }
    return count;
}

void dump_queues() {
    static bool parsed = false;
    static int32_t addresses[16];
    static int count = 0;

    if (!parsed) {
        parsed = true;
        const char* spec = std::getenv("SCARS_QUEUES");
        if (spec != nullptr) {
            const char* cursor = spec;
            while (*cursor != '\0' && count < 16) {
                while (*cursor == ',' || *cursor == ' ') {
                    cursor++;
                }
                if (*cursor == '\0') {
                    break;
                }
                char* end = nullptr;
                const unsigned long value = std::strtoul(cursor, &end, 16);
                if (end == cursor) {
                    break;
                }
                addresses[count++] = static_cast<int32_t>(value);
                cursor = end;
            }
        }
    }

    uint8_t* rdram = guest_hw_rdram();
    if (rdram == nullptr || count == 0) {
        return;
    }

    for (int i = 0; i < count; i++) {
        const int32_t address = addresses[i];
        const int32_t valid = read_guest_word(rdram, address + kQueueValidCount);
        const int32_t size = read_guest_word(rdram, address + kQueueMsgCount);
        const int32_t recv_head = read_guest_word(rdram, address + kQueueBlockedRecv);
        char ids[64] = "";
        const int waiters = blocked_thread_count(rdram, recv_head, ids, sizeof(ids));
        logf("queue 0x%08X: valid=%d/%d waiters=%d [%s]", static_cast<uint32_t>(address), valid, size, waiters, ids);
    }
}

} // namespace

void on_vi() {
    guest_hw_tick();
    const unsigned long long index = vis.fetch_add(1) + 1;
    log_throttled("vi", 5, "VI #%llu", index);

    // A rolling summary: whether the guest keeps producing graphics/audio work
    // is the first thing to look at when a frame looks frozen.
    if (index % 120 == 0) {
        // Stall detector: the guest stops submitting RSP tasks entirely when the
        // scheduler loses a wake-up. Dump the last scheduling events once, from
        // the VI thread, so the fast (untraced) run that reproduces it is enough.
        static unsigned long long last_rsp_here = 0;
        static bool stall_dumped = false;
        const unsigned long long rsp_now = rsp_tasks.load();
        if (!stall_dumped && rsp_now == last_rsp_here) {
            stall_dumped = true;
            scars_sched_dump_recent("rsp task counter stopped advancing");
        }
        last_rsp_here = rsp_now;

        const auto* vi = ultramodern::renderer::get_vi_regs();
        logf("status: vis=%llu gfx=%llu rsp=%llu audio=%llu ai_len=%u vi_origin=0x%08X vi_width=0x%X "
             "vi_status=0x%08X",
             index, gfx_tasks.load(), rsp_tasks.load(), audio_buffers.load(), guest_hw_audio_remaining(),
             vi->VI_ORIGIN_REG, vi->VI_WIDTH_REG, vi->VI_STATUS_REG);
        dump_queues();
    }
}

