std::string game_thread_name(const OSThread* thread) {
    scars::logf("guest thread start: id=%d state=%d sp=0x%08X", thread->id, static_cast<int>(thread->state),
                static_cast<uint32_t>(thread->sp));
    char buffer[32];
    std::snprintf(buffer, sizeof(buffer), "scars-thread-%d", thread->id);
    return buffer;
}

